{"file_path":"src/address.js","content":"/**
 * Cell address parsing and ordering. An address is one or two letters
 * naming a column (A..Z, AA..ZZ) followed by one to three digits naming a
 * row of at least 1, with no leading zero on the row.
 */

const ADDRESS_RE = /^[A-Za-z]{1,2}[1-9][0-9]{0,2}$/

/** Splits a word into its letter run and digit run (digits may be empty). */
export function splitWord(word) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(word)
  return { letters: m[1], digits: m[2] }
}

export function columnNumber(lettersUpper) {
  let n = 0
  for (const ch of lettersUpper) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/**
 * Parses a word as a cell address. Returns { valid, addr, col, row } where
 * addr is the canonical upper-cased "COL"+"ROW" string when valid.
 */
export function parseAddress(word) {
  const upper = word.toUpperCase()
  if (!ADDRESS_RE.test(upper)) return { valid: false }
  const { letters, digits } = splitWord(upper)
  return { valid: true, addr: upper, col: columnNumber(letters), row: Number(digits) }
}

/** Sort key comparator for two addresses (by column, then by row). */
export function compareAddresses(a, b) {
  const pa = parseAddress(a)
  const pb = parseAddress(b)
  if (pa.col !== pb.col) return pa.col - pb.col
  return pa.row - pb.row
}
"}

