{"file_path":"src/tokenizer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 */

const TOKEN_MATCHERS = [
  ['NUM', /^[0-9]+(?:\.[0-9]+)?/],
  ['WORD', /^[A-Za-z]+[0-9]*/],
  ['LE', /^<=/],
  ['GE', /^>=/],
  ['NE', /^<>/],
  ['LT', /^</],
  ['GT', /^>/],
  ['EQ', /^=/],
  ['PLUS', /^\+/],
  ['MINUS', /^-/],
  ['STAR', /^\*/],
  ['SLASH', /^\//],
  ['CARET', /^\^/],
  ['LP', /^\(/],
  ['RP', /^\)/],
  ['COMMA', /^,/],
  ['COLON', /^:/],
]

/**
 * Tokenizes a formula body. Returns { ok: true, tokens } on success or
 * { ok: false } when an unrecognized character is found.
 */
export function tokenize(body) {
  const tokens = []
  let pos = 0
  while (pos < body.length) {
    const ch = body[pos]
    if (ch === ' ' || ch === '\t') {
      pos += 1
      continue
    }
    const rest = body.slice(pos)
    let matched = null
    for (const [type, re] of TOKEN_MATCHERS) {
      const m = re.exec(rest)
      if (m) {
        matched = { type, value: m[0] }
        break
      }
    }
    if (!matched) return { ok: false }
    tokens.push(matched)
    pos += matched.value.length
  }
  tokens.push({ type: 'EOF', value: '' })
  return { ok: true, tokens }
}
"}

