{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies, producing an AST or null
 * when the body is not accepted by the grammar.
 *
 * AST node shapes:
 *   { type: 'num', value }
 *   { type: 'bool', value }
 *   { type: 'addr', raw }               -- a bare word read as a cell address
 *   { type: 'range', from, to }         -- from/to are the raw address words
 *   { type: 'call', name, args }        -- args are 'range' or expression nodes
 *   { type: 'unary', op, operand }
 *   { type: 'bin', op, left, right }
 */

import { tokenize } from './tokenizer.js'

class ParseError extends Error {}

const COMPARISON_TYPES = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])

function makeParser(tokens) {
  let pos = 0
  const peek = (offset = 0) => tokens[pos + offset] ?? { type: 'EOF', value: '' }
  const next = () => tokens[pos++]
  const expect = (type) => {
    if (peek().type !== type) throw new ParseError(`expected ${type}`)
    return next()
  }

  function parsePrimary() {
    const tok = peek()
    if (tok.type === 'NUM') {
      next()
      return { type: 'num', value: Number(tok.value) }
    }
    if (tok.type === 'LP') {
      next()
      const inner = parseComparison()
      expect('RP')
      return inner
    }
    if (tok.type === 'WORD') {
      const upper = tok.value.toUpperCase()
      if (peek(1).type === 'LP') {
        next()
        next() // consume LP
        const args = parseArgs()
        expect('RP')
        return { type: 'call', name: upper, args }
      }
      if (upper === 'TRUE' || upper === 'FALSE') {
        next()
        return { type: 'bool', value: upper === 'TRUE' }
      }
      next()
      return { type: 'addr', raw: tok.value }
    }
    throw new ParseError(`unexpected token ${tok.type}`)
  }

  function parsePrimaryWithSign() {
    const tok = peek()
    if (tok.type === 'PLUS' || tok.type === 'MINUS') {
      next()
      const operand = parsePrimaryWithSign()
      return { type: 'unary', op: tok.type === 'PLUS' ? '+' : '-', operand }
    }
    return parsePrimary()
  }

  function parsePower() {
    const base = parsePrimaryWithSign()
    if (peek().type === 'CARET') {
      next()
      const exponent = parsePower()
      return { type: 'bin', op: '^', left: base, right: exponent }
    }
    return base
  }

  function parseMultiplicative() {
    let left = parsePower()
    while (peek().type === 'STAR' || peek().type === 'SLASH') {
      const op = next().type === 'STAR' ? '*' : '/'
      const right = parsePower()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    while (peek().type === 'PLUS' || peek().type === 'MINUS') {
      const op = next().type === 'PLUS' ? '+' : '-'
      const right = parseMultiplicative()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  function parseComparison() {
    let left = parseAdditive()
    while (COMPARISON_TYPES.has(peek().type)) {
      const opTok = next()
      const right = parseAdditive()
      left = { type: 'bin', op: opTok.type, left, right }
    }
    return left
  }

  function parseOneArg() {
    if (peek().type === 'WORD' && peek(1).type === 'COLON' && peek(2).type === 'WORD') {
      const from = next().value
      next() // COLON
      const to = next().value
      return { type: 'range', from, to }
    }
    return parseComparison()
  }

  function parseArgs() {
    const args = []
    if (peek().type === 'RP') return args
    args.push(parseOneArg())
    while (peek().type === 'COMMA') {
      next()
      args.push(parseOneArg())
    }
    return args
  }

  return { parseComparison, atEnd: () => peek().type === 'EOF' }
}

/** Parses a formula body (without the leading `=`). Returns an AST or null. */
export function parseFormula(body) {
  const lex = tokenize(body)
  if (!lex.ok) return null
  const parser = makeParser(lex.tokens)
  try {
    const ast = parser.parseComparison()
    if (!parser.atEnd()) return null
    return ast
  } catch (e) {
    if (e instanceof ParseError) return null
    throw e
  }
}
"}

