{"file_path":"src/values.js","content":"/**
 * Value representation: a number, text, a boolean, or an error. Errors are
 * represented by their literal token, e.g. `#DIV/0!`.
 */

export const numVal = (v) => ({ t: 'num', v })
export const textVal = (v) => ({ t: 'text', v })
export const boolVal = (v) => ({ t: 'bool', v })
export const errVal = (v) => ({ t: 'err', v })

export const isErr = (v) => v.t === 'err'

export const ERR_DIV0 = '#DIV/0!'
export const ERR_REF = '#REF!'
export const ERR_VALUE = '#VALUE!'
export const ERR_CYCLE = '#CYCLE!'
export const ERR_NAME = '#NAME?'
export const ERR_ERR = '#ERR!'

export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

/** Reads a value in an arithmetic position as a number-or-error value. */
export function toNumber(v) {
  if (v.t === 'err') return v
  if (v.t === 'num') return v
  if (v.t === 'bool') return numVal(v.v ? 1 : 0)
  return errVal(ERR_VALUE)
}

/** Wraps an arithmetic result, turning any non-finite result into #DIV/0!. */
export function finiteOrDiv0(n) {
  return Number.isFinite(n) ? numVal(n) : errVal(ERR_DIV0)
}

function typeRank(v) {
  if (v.t === 'num') return 0
  if (v.t === 'text') return 1
  return 2 // bool
}

/** Total order across values used for comparisons: -1, 0, or 1. */
export function compareValues(a, b) {
  const ra = typeRank(a)
  const rb = typeRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

/** Formats a number as JavaScript would, after rounding to 10 significant digits. */
export function formatNumber(n) {
  if (n === 0) return '0'
  return Number(n.toPrecision(10)).toString()
}

/** Formats a value for the `values` command's `<address>=<value>` output. */
export function formatValue(v) {
  if (v.t === 'num') return formatNumber(v.v)
  if (v.t === 'text') return v.v
  if (v.t === 'bool') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}
"}

