{"file_path":"src/sheet.js","content":"/**
 * Parses sheet input into a map of declared cells, in declaration order.
 */

import { parseAddress } from './address.js'
import { parseFormula } from './parser.js'
import { numVal, textVal, errVal, ERROR_TOKENS } from './values.js'

const NUMBER_RE = /^-?[0-9]+(?:\.[0-9]+)?$/

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/** Classifies literal (non-formula) content into a value. */
function literalValue(content) {
  if (content === '') return numVal(0)
  if (NUMBER_RE.test(content)) return numVal(Number(content))
  if (ERROR_TOKENS.has(content)) return errVal(content)
  return textVal(content)
}

/**
 * Parses the whole sheet. Returns { order, cells } where order is the list
 * of declared addresses in first-seen order and cells maps address to
 * { kind: 'literal', value } or { kind: 'formula', ast }.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  const order = []

  lines.forEach((rawLine, index) => {
    const lineNo = index + 1
    const stripped = rawLine.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) return

    const m = /^([^ \t]+)(?:[ \t](.*))?$/.exec(stripped)
    const addressToken = m[1]
    const content = m[2] ?? ''

    const parsed = parseAddress(addressToken)
    if (!parsed.valid) {
      throw new SheetError(lineNo, `invalid cell address ${addressToken.toUpperCase()}`)
    }
    const addr = parsed.addr
    if (cells.has(addr)) {
      throw new SheetError(lineNo, `cell ${addr} is declared twice`)
    }

    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      cells.set(addr, { kind: 'formula', ast })
    } else {
      cells.set(addr, { kind: 'literal', value: literalValue(content) })
    }
    order.push(addr)
  })

  return { order, cells }
}
"}

