      }
    }

    const ln = toNumber(left)
    if (isErr(ln)) return ln
    const rn = toNumber(right)
    if (isErr(rn)) return rn
    switch (node.op) {
      case '+':
        return finiteOrDiv0(ln.v + rn.v)
      case '-':
        return finiteOrDiv0(ln.v - rn.v)
      case '*':
        return finiteOrDiv0(ln.v * rn.v)
      case '/':
        return finiteOrDiv0(ln.v / rn.v)
      case '^':
        return finiteOrDiv0(Math.pow(ln.v, rn.v))
