  function toBool(v) {
    if (isErr(v)) return v
    if (v.t === 'bool') return v
    if (v.t === 'num') return boolVal(v.v !== 0)
    return errVal(ERR_VALUE)
  }

  function evalCall(node) {
    const name = node.name
    if (!KNOWN_FUNCTIONS.has(name)) return errVal(ERR_NAME)

