    if (node.args.length < 1) return errVal(ERR_ERR)
    const values = []
    for (const arg of node.args) values.push(...expandArgValues(arg))
    const firstErr = values.find(isErr)
    if (firstErr) return firstErr

    if (name === 'COUNT') {
      return numVal(values.filter((v) => v.t === 'num').length)
    }

