 * Evaluates cell formulas against a parsed sheet, with memoization and
 * cycle detection.
 */

import { parseAddress, columnNumber } from './address.js'
import {
  numVal,
  textVal,
  boolVal,
  errVal,
  isErr,
  toNumber,
  finiteOrDiv0,
  compareValues,
  ERR_REF,
  ERR_CYCLE,
  ERR_VALUE,
  ERR_NAME,
  ERR_ERR,
} from './values.js'

const KNOWN_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

const COMPARISON_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])

/** Expands a range's two corner words into the list of addresses it covers. */
function expandRangeAddresses(fromWord, toWord) {
  const from = parseAddress(fromWord)
  const to = parseAddress(toWord)
  if (!from.valid || !to.valid) return null
  const colMin = Math.min(from.col, to.col)
  const colMax = Math.max(from.col, to.col)
  const rowMin = Math.min(from.row, to.row)
  const rowMax = Math.max(from.row, to.row)
  const addrs = []
  for (let col = colMin; col <= colMax; col++) {
    for (let row = rowMin; row <= rowMax; row++) {
      addrs.push(colRowToAddr(col, row))
    }
  }
  return addrs
}

function colRowToAddr(col, row) {
  let letters = ''
  let c = col
  while (c > 0) {
    const rem = (c - 1) % 26
    letters = String.fromCharCode(65 + rem) + letters
    c = Math.floor((c - 1) / 26)
  }
  return letters + String(row)
}

export function makeEvaluator(sheet) {
  const cache = new Map() // addr -> { status: 'visiting' | 'done', value }

  function evaluateCell(addr) {
    const existing = cache.get(addr)
    if (existing) {
      if (existing.status === 'visiting') return errVal(ERR_CYCLE)
      return existing.value
    }
    cache.set(addr, { status: 'visiting' })
    const decl = sheet.cells.get(addr)
    let result
    if (!decl) {
      result = numVal(0)
    } else if (decl.kind === 'literal') {
      result = decl.value
    } else if (decl.ast === null) {
      result = errVal(ERR_ERR)
    } else {
      result = evalNode(decl.ast)
    }
    cache.set(addr, { status: 'done', value: result })
    return result
  }

  function evalAddrNode(node) {
    const parsed = parseAddress(node.raw)
    if (!parsed.valid) return errVal(ERR_REF)
    return evaluateCell(parsed.addr)
  }

  /** Evaluates a single argument node, expanding a range into a flat list. */
  function expandArgValues(node) {
    if (node.type === 'range') {
      const addrs = expandRangeAddresses(node.from, node.to)
      if (addrs === null) return [errVal(ERR_REF)]
      return addrs.map(evaluateCell)
    }
    return [evalNode(node)]
  }

  function evalNode(node) {
    switch (node.type) {
      case 'num':
        return numVal(node.value)
      case 'bool':
        return boolVal(node.value)
      case 'addr':
        return evalAddrNode(node)
      case 'unary':
        return evalUnary(node)
      case 'bin':
        return evalBin(node)
      case 'call':
        return evalCall(node)
      default:
        throw new Error(`unexpected node type ${node.type}`)
    }
  }

  function evalUnary(node) {
    const operand = evalNode(node.operand)
    if (isErr(operand)) return operand
    const n = toNumber(operand)
    if (isErr(n)) return n
    return numVal(node.op === '-' ? -n.v : n.v)
  }

  function evalBin(node) {
    const left = evalNode(node.left)
    if (isErr(left)) return left
    const right = evalNode(node.right)
    if (isErr(right)) return right

    if (COMPARISON_OPS.has(node.op)) {
      const cmp = compareValues(left, right)
      switch (node.op) {
        case 'EQ':
          return boolVal(cmp === 0)
        case 'NE':
          return boolVal(cmp !== 0)
        case 'LT':
          return boolVal(cmp < 0)
        case 'LE':
          return boolVal(cmp <= 0)
        case 'GT':
          return boolVal(cmp > 0)
        case 'GE':
          return boolVal(cmp >= 0)
      }
    }

    const ln = toNumber(left)
    if (isErr(ln)) return ln
    const rn = toNumber(right)
    if (isErr(rn)) return rn
    switch (node.op) {
      case '+':
        return finiteOrDiv0(ln.v + rn.v)
      case '-':
        return finiteOrDiv0(ln.v - rn.v)
      case '*':
        return finiteOrDiv0(ln.v * rn.v)
      case '/':
        return finiteOrDiv0(ln.v / rn.v)
      case '^':
        return finiteOrDiv0(Math.pow(ln.v, rn.v))
      default:
        throw new Error(`unexpected operator ${node.op}`)
    }
  }

  function toBool(v) {
    if (isErr(v)) return v
    if (v.t === 'bool') return v
    if (v.t === 'num') return boolVal(v.v !== 0)
    return errVal(ERR_VALUE)
  }

  function evalCall(node) {
    const name = node.name
    if (!KNOWN_FUNCTIONS.has(name)) return errVal(ERR_NAME)

    if (name === 'IF') {
      if (node.args.length !== 3) return errVal(ERR_ERR)
      const condValues = expandArgValues(node.args[0])
      const firstErr = condValues.find(isErr)
      if (firstErr) return firstErr
      const cond = toBool(condValues[0])
      if (isErr(cond)) return cond
      const branch = cond.v ? node.args[1] : node.args[2]
      const branchValues = expandArgValues(branch)
      return branchValues[0]
    }

    if (name === 'ABS') {
      if (node.args.length !== 1) return errVal(ERR_ERR)
      const values = expandArgValues(node.args[0])
      const firstErr = values.find(isErr)
      if (firstErr) return firstErr
      let total = 0
      for (const v of values) {
        const n = toNumber(v)
        if (isErr(n)) return n
        total += n.v
      }
      return finiteOrDiv0(Math.abs(total))
    }

    // SUM, MIN, MAX, COUNT, AVG: one or more arguments, ranges expanded.
    if (node.args.length < 1) return errVal(ERR_ERR)
    const values = []
    for (const arg of node.args) values.push(...expandArgValues(arg))
    const firstErr = values.find(isErr)
    if (firstErr) return firstErr

    if (name === 'COUNT') {
      return numVal(values.filter((v) => v.t === 'num').length)
    }

    const numbers = []
    for (const v of values) {
      const n = toNumber(v)
      if (isErr(n)) return n
      numbers.push(n.v)
    }
    if (name === 'SUM') return finiteOrDiv0(numbers.reduce((a, b) => a + b, 0))
    if (name === 'AVG') return finiteOrDiv0(numbers.reduce((a, b) => a + b, 0) / numbers.length)
    if (name === 'MIN') return finiteOrDiv0(Math.min(...numbers))
    if (name === 'MAX') return finiteOrDiv0(Math.max(...numbers))
