{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { compareAddresses } from './address.js'
import { makeEvaluator } from './evaluator.js'
import { collectDeps } from './deps.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
    }
    throw e
  }

  const addrs = [...sheet.order].sort(compareAddresses)
  const lines = []

  if (mode === 'values') {
    const evaluator = makeEvaluator(sheet)
    for (const addr of addrs) {
      const value = evaluator.evaluateCell(addr)
      lines.push(`${addr}=${formatValue(value)}`)
    }
  } else {
    for (const addr of addrs) {
      const decl = sheet.cells.get(addr)
      let deps = []
      if (decl.kind === 'formula' && decl.ast !== null) {
        deps = [...collectDeps(decl.ast)].sort(compareAddresses)
      }
      lines.push(`${addr}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }

  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

